UPDATE companies SET description='Founded in 1984 as a wholly owned subsidiary of Tama Chemicals, Moses Lake Industries (MLI) operates its global headquarters in Moses Lake, Washington, with additional operations in Mesa, Arizona. The company began with a single product and a founder''s vision to build an enduring enterprise for future generations.

MLI develops and manufactures ultra-high-purity chemistries for the semiconductor industry, offering a portfolio that has grown to over 1,000 products. Its capabilities span advanced packaging, IC substrate, Damascene, TMAH, and analytical reagent formulations. The company provides localized manufacturing, technical support, R&D services, and distribution through multiple plants worldwide. In-house raw material synthesis, proprietary manufacturing systems designed and managed by internal experts, real-time analytical monitoring, and strict packaging and shipping controls underpin its production process.

The company serves semiconductor manufacturers and advanced technology firms, collaborating closely with chip makers to develop next-generation solutions. Its customer base includes global semiconductor fabs requiring high-performance chemical solutions for cutting-edge device production.

MLI differentiates itself through a quality operating system built on Failure Mode and Effects Analysis (FMEA), in-house raw material production, and a Certificate of Analysis provided with every shipment. The founder''s original vision—to create a lasting enterprise invested in people, community, and environment—continues to drive its focus on innovative, operational, and financial excellence.', certifications=ARRAY['ISO 9001:2015','ISO 45001:2018','ISO 14001:2015']::text[], profile='{"capabilities": ["Semiconductor chemistry development", "Semiconductor chemistry manufacturing", "Advanced packaging chemistries", "IC substrate chemistries", "Damascene process chemistries", "TMAH solutions", "Analytical reagents", "Localized manufacturing", "Technical support", "R&D services", "Distribution", "Raw material synthesis", "In-house manufacturing systems design", "Real-time production monitoring", "Failure Mode and Effects Analysis (FMEA)", "Strict packaging and contamination control", "Controlled warehousing and shipping", "Quality management system (ISO 9001:2015)", "Customer support and collaboration"], "industries": ["Semiconductor"], "materials": ["Ultra-high-purity semiconductor chemicals", "Organic additives", "TMAH (tetramethylammonium hydroxide)", "Analytical reagents"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Portfolio of over 1,000 semiconductor chemistry products", "In-house raw material manufacturing for quality control", "Proprietary manufacturing systems designed and managed internally", "Real-time analytical monitoring with immediate in-line corrective response", "Certificate of Analysis included with every shipment"], "facts_used": ["Founded in 1984 as wholly owned subsidiary of Tama Chemicals -> /about", "Global headquarters in Moses Lake, Washington -> /about", "Operations in Mesa, Arizona -> db", "Portfolio grown to over 1,000 products -> /about", "Capabilities: advanced packaging, IC substrate, Damascene, TMAH, analytical reagents -> /", "Localized manufacturing, technical support, R&D services, distribution -> /", "In-house raw material manufacturing -> /about", "In-house design/build/manage manufacturing systems -> /about", "Advanced analytical devices for real-time monitoring -> /about", "Strict packaging specifications, cleaning methodologies -> /about", "Certificate of Analysis with each shipment -> /about", "Controlled warehouse and shipping conditions -> /about", "Quality Management System with FMEA -> /about", "Certifications: ISO 9001:2015, ISO 45001:2018, ISO 14001:2015 -> /about", "Serves semiconductor industry, leading chip manufacturers -> /about", "Founder''s vision: enduring enterprise for future generations -> /about", "Values: Safety, Integrity, Collaboration, Ownership, Sustainability, Service -> /about"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='moses-lake-industries' AND approved AND profile IS NULL;
UPDATE companies SET description='Motherlode Co-Packing operates from Hudson, Colorado, about 30 minutes from Denver International Airport. The company was founded in 1966 and has grown into a certified co-packing facility serving food brands nationwide.

The facility provides end-to-end co-packing services for sauces, syrups, dressings, condiments, and beverages. Its process covers formulation development with food scientists, bottling in glass, plastic, or pouch formats, and automation for scale-up. The plant is FDA, HACCP, and SQF approved and runs thousands of gallons per week.

Motherlode works with established food brands on both coasts that are poised for sales growth. Customers include sauce and condiment companies, a vegan food brand, and a restauranteur launching a sauce line. The company also connects brands with its investor network for capital raises and leverages a vendor rolodex for supply chain support.

The company emphasizes transformative relationships, integrity, and innovative processes. It was voted 2021 Colorado Food Manufacturer of the Year and holds a 99/100 food safety rating. All ingredients used are non-GMO. Motherlode differentiates itself by offering integrated capital, logistics, and value-engineering services alongside core co-packing.', certifications=ARRAY['HACCP','SQF']::text[], profile='{"capabilities": ["Co-packing (contract packaging)", "Formulation development", "Product development (food science)", "Bottling and filling (glass, plastic, pouch)", "Process automation and scale-up", "Supply chain management", "Logistics and fulfillment (LTL/TL, 3PL)", "Value engineering", "Capital raising assistance", "Quality and food safety management", "Regulatory compliance (FDA, HACCP, SQF)"], "industries": ["Food and beverage manufacturing", "Sauce and condiment production", "Syrup and dressing production", "Beverage production", "Food service", "Retail food products"], "materials": ["Glass containers", "Plastic containers", "Pouch packaging", "Food ingredients (sauces, syrups, dressings, condiments, beverages)"], "equipment": [], "volume": "Thousands of gallons per week", "lead_time": "", "tolerances": "", "built_on": ["Central U.S. location enabling guaranteed shipment schedules and freight savings", "Integrated investor network for capital raises", "Supply chain vendor network and logistics fulfillment support", "Value engineering to improve production efficiency and cost of goods", "99/100 food safety rating and non-GMO ingredient commitment"], "facts_used": ["Founded 1966 -> db", "Headquarters Hudson, Colorado -> db", "Facility 30 min from Denver International Airport -> /", "FDA/HACCP/SQF approved facility -> /", "Thousands of gallons per week capacity -> /about", "Glass, plastic, pouch packaging options -> /, /about", "Formulation development with food scientists -> /", "Capital raises via investor network -> /, /about", "Supply chain vendor network -> /, /about", "Logistics & fulfillment support (LTL/TL, 3PL) -> /, /about", "Value engineering services -> /, /about", "2021 Colorado Food Manufacturer of the Year -> /about", "99/100 food safety rating -> /about", "Non-GMO ingredients -> /about", "Leadership team: Jim (CEO), Greg (COO), Kit (CCO), Amber (Dir. Admin), Josh (Plant Mgr), Tanya (Dir. Quality/Food Safety), Dan (Plant Engineer) -> /about", "Customer examples: sauce company, vegan food brand, restauranteur -> /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='motherlode-co-packing-corporate-offices' AND approved AND profile IS NULL;
UPDATE companies SET description='The company relocated to a 35,000-square-foot headquarters in Cedar Rapids in 1990 and added a 20,000-square-foot facility in Greenville, South Carolina, in 2001. A 12,000-square-foot expansion in Cedar Rapids followed in 2015. Now in its third generation, the business is led by CEO Roger Klouda and President Kyle Klouda.

The company designs and builds steel and aluminum injection molds for processes including structural foam, reaction injection molding (RIM), blow molding, gas assist, and structural web, as well as aluminum tooling for limited production. MSI specializes in large-tonnage molds weighing up to 150,000 pounds, supported by two U.S. Since 1971, the firm has delivered thousands of molds across a range of sizes and complexities, offering end-to-end services from design and engineering through in-house sampling, repair, and preventative maintenance.

MSI serves OEMs and suppliers in automotive, power sports, agriculture, lawn and garden, medical equipment, heavy truck, material handling, recreational vehicles, construction, office furniture, solar, energy distribution, infrastructure, data centers, and appliance industries. Notable projects include tooling for the AxSYM medical program and reusable pallets for the solar industry.

The company emphasizes a process-driven approach rooted in Lean Manufacturing, with early data validation, cross-functional design reviews, and in-process quality checks to reduce risk and ensure repeatable lead times. Domestic production is positioned to shorten supply chains, improve communication, and enable faster design changes and on-site collaboration.', certifications=ARRAY['ISO 9001:2008']::text[], profile='{"capabilities": ["Mold Design & Engineering", "Mold Construction", "In-house Sampling & Tryout", "Tool Revision, Repair & Maintenance", "Injection Mold Building", "Structural Foam Mold Building", "Reaction Injection Molding (RIM) Mold Building", "Blow Mold Building", "Gas Assist Mold Building", "Structural Web Mold Building", "Aluminum Tooling for Limited Production", "Large-Tonnage Mold Building (up to 150,000 lbs)", "End-to-End Lifecycle Support", "Lean Manufacturing Processes", "Early Design Involvement", "Cross-Functional Design Reviews", "In-Process Quality Checks"], "industries": ["Automotive", "Power Sports", "Agriculture", "Lawn and Garden", "Medical Equipment", "Heavy Truck", "Material Handling", "Recreational Vehicles", "Construction", "Office Furniture", "Solar", "Energy Distribution", "Infrastructure", "Data Centers", "Appliance"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Process-driven organization built on Lean Manufacturing principles", "Early data validation and cross-functional design reviews", "In-house sampling for faster adjustments and reduced risk", "Two U.S. facilities enabling domestic supply chain and on-site collaboration", "Large-tonnage mold capability up to 150,000 pounds"], "facts_used": ["Founded 1971 by Ed and CharLes Klouda in Swisher, Iowa -> /about", "Relocated to 35,000 sq ft Cedar Rapids headquarters in 1990 -> /about", "Opened 20,000 sq ft Greenville, SC facility in 2001 -> /about", "Achieved ISO 9001:2008 certification in 2010 -> /about", "Completed 12,000 sq ft Cedar Rapids expansion in 2015 -> /about", "Leadership transition: Roger Klouda to CEO, Kyle Klouda president in 2022 -> /about", "Two facilities in Cedar Rapids, IA and Greenville, SC -> /, /about", "Specializes in large-tonnage molds up to 150,000 lbs -> /capabilities", "Processes: injection, structural foam, RIM, blow, gas assist, structural web, aluminum limited-production -> /capabilities, /about", "Industries served: automotive, power sport, agriculture, lawn/garden, medical, heavy truck, material handling, recreational vehicle, construction, office furniture, solar, energy distribution, infrastructure, data centers, appliance -> /about, /capabilities", "Capabilities: design & engineering, mold construction, in-house sampling, tool revision/repair/maintenance -> /capabilities", "Awards: Tooling Trail Blazer Award 2018, Leadtime Leader honorable mentions 2016/2011/2006, Best Overall Use Award 2008, Tooling Supplier of the Year 2008, Alliance of Plastic Parts awards 2006 -> /about", "Lean Manufacturing principles, process-driven, early data validation, cross-functional design reviews, in-process quality checks -> /capabilities", "End-to-end lifecycle support -> /capabilities", "Domestic/U.S. manufacturing focus -> /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='msi-mold-builders' AND approved AND profile IS NULL;
UPDATE companies SET description='NEP was founded in 1977 by Bill Federighi and Tom Lotus, two former regional sales managers who saw a need for a customer-first approach in the electronics industry. The company began as NEP Electronics, a distribution business in Chicago, Illinois, and moved to a 35,000-square-foot facility in Wood Dale, Illinois, in 1988. A 40,000-square-foot manufacturing building was added next door in 2009, and a 2025 expansion brought an additional 10,000 square feet of production space and 5,000 square feet of offices to the Wood Dale campus.

Today NEP provides custom cable assemblies, wire harnesses, electro-mechanical assemblies, and full contract manufacturing including box builds, panel and enclosure assembly, and system integration. Its capabilities cover wire processing from 32 AWG to 4/0, high-speed robotic cutting, stripping, crimping, tinning, and printing, multi-stage coaxial processing, and hydraulic crimping for battery and welding cables. The company operates with a workforce that includes more than 40 employees who have been with the firm for over a decade, supporting prototype through high-volume production runs.

NEP serves a range of industries including agriculture, food processing, gaming and coin-operated equipment, industrial equipment, medical devices, robotics, transportation, and utility/energy sectors. Customers also come from technology and communications markets, as reflected in testimonials from buyers in those fields.

The company differentiates itself through vertical integration that combines franchised component distribution (45+ lines) with engineering support, first-article verification, DFM analysis, and rigorous quality testing including 100% continuity, hi-pot, and terminal pull tests. It holds ISO 9001:2015 certification, UL recognition, and ITAR compliance, and offers vendor-managed inventory and just-in-time delivery programs.', certifications=ARRAY['ISO 9001:2015','UL Recognized','ITAR Compliant']::text[], profile='{"capabilities": ["Custom cable assembly", "Wire harness fabrication", "Electro-mechanical assembly", "Contract manufacturing (box build)", "Panel and enclosure assembly", "DIN rail and terminal block assembly", "Control panel assembly", "Power supply assembly", "Overmolded cable assembly", "RF/coaxial cable assembly", "Code lug and battery/welding cable assembly", "Switch and LED harness assembly", "Sensor cable assembly", "Motor cable assembly", "Fan and fan tray assembly", "Multi-conductor cable assembly", "Ribbon and FFC cable assembly", "IDC cable assembly", "High-speed robotic wire processing (cut, strip, crimp, tin, print)", "Hydraulic crimping", "Multi-stage coaxial processing", "First article inspection and verification", "Design for manufacturability (DFM) evaluation", "Vendor-managed inventory (VMI) and JIT delivery"], "industries": ["Agriculture", "Food Processing", "Gaming/Coin-Op", "Industrial", "Medical Devices", "Robotics", "Transportation", "Utility/Energy", "Technology", "Communications"], "materials": [], "equipment": [], "volume": "Prototype to high-volume production", "lead_time": "", "tolerances": "", "built_on": ["100% continuity testing on every assembly", "In-house IPC 620 and J-STD certified trainers", "Franchised distributor for 45+ component lines", "High-speed robotic wire processing (32 AWG to 4/0)", "Hydraulic crimping for battery/welding cables and code lugs"], "facts_used": ["Founded 1977 by Bill Federighi and Tom Lotus -> /about-us", "Headquartered in Wood Dale, Illinois -> /about-us, db", "Facility expansions: 35,000 sq ft (1988), 40,000 sq ft (2009), 10,000 sq ft added 2025 -> /about-us", "Over 40 employees with 10+ year tenure -> /about-us", "ISO 9001:2015, UL recognized, ITAR compliant -> /", "Wire processing 32 AWG-4/0, high-speed robotics, hydraulic crimping -> /", "Industries served: Agriculture, Food Processing, Gaming/Coin-Op, Industrial, Medical, Robotics, Transportation, Utility/Energy -> /services", "Franchised distributor for 45+ lines -> /", "Engineering support, DFM, first article verification -> /services", "Vendor-managed inventory, JIT delivery -> /", "Custom test fixturing, full system testing -> /", "100% continuity testing, hi-pot, terminal pull testing -> /", "IPC 620, J-STD in-house trainers -> /", "Component sourcing with 3M, Panduit, JST, Molex -> /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='nep-custom-cable-assembly-manufacturer' AND approved AND profile IS NULL;
UPDATE companies SET description='The company operates as a Tier 1 automotive supplier serving major OEMs across North America.

The company designs and manufactures steering wheels, airbag modules, decorative interior trim, exterior components, resin parts, leather-wrapped steering wheels, and magnesium components. Its manufacturing processes include injection molding, blow molding, painting, welding, assembly, wrapping, sewing, and reaction injection molding (RIM). The primary Eaton campus spans over 565,000 square feet of production space, with additional U.S. facilities in Marysville, Ohio (sales and technical support) and Rome, Georgia (painting, assembly, and cockpit trim). Operations extend to multiple sites in Mexico and a network of Nihon Plast plants in China, Vietnam, Thailand, and Indonesia. North American sales exceeded $300 million in 2023.

Neaton serves the automotive industry, specifically major OEMs requiring safety systems such as airbag modules and steering wheels, as well as interior and exterior trim components. Its customer base includes automakers across North America, supported by deep integration with OEM platforms and end-to-end product development from tooling to final assembly.

The company emphasizes decades of technical expertise in safety systems, decorative trim, and blow-molded parts, along with on-site design support and IATF 16949-certified quality systems. President Takeshi (Casey) Toyota states the business is built by and for its associates, aiming to bring smiles to employees, customers, and communities.', certifications=ARRAY['IATF 16949']::text[], profile='{"capabilities": ["Injection molding", "Blow molding", "Painting", "Welding", "Assembly", "Wrapping", "Sewing", "Reaction injection molding (RIM)", "Magnesium component manufacturing", "Leather wrapping", "Airbag module assembly", "Steering wheel manufacturing", "On-site design support", "Tooling development"], "industries": ["Automotive", "Automotive safety systems", "Automotive trim systems", "OEM automotive"], "materials": ["Plastics", "Resin", "Leather", "Magnesium"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Decades of technical expertise in safety systems, decorative trim, and blow-molded parts", "Deep integration with leading OEMs", "End-to-end product development from tooling to assembly", "North American sales exceeded $300 million in 2023", "IATF 16949 certified quality systems with on-site design support"], "facts_used": ["Founded 1984 in Eaton, Ohio -> /about", "Wholly owned subsidiary of Nihon Plast Co., Ltd. -> /about", "Tier 1 automotive supplier serving major OEMs across North America -> /about", "Primary Eaton campus over 565,000 sq ft production space -> /about", "Facilities in Marysville OH, Rome GA, Monterrey Mexico, Queretaro Mexico, Temascalcingo Mexico -> /about", "Asian Nihon Plast plants in Wuhan, Zhongshan, Vietnam, Thailand, Indonesia -> /about", "Products: steering wheels, airbag modules, interior trim, exterior trim, resin components, leather-wrapped steering wheels, magnesium components -> /about, /", "Processes: injection molding, blow molding, paint, weld, assembly, wrapping, sewing, RIM -> /, /about", "North American sales exceeded $300M in 2023 -> /", "IATF 16949 certified quality systems -> /, db", "On-site design support -> /", "President Takeshi (Casey) Toyota -> /about", "Company built by associates for associates -> /about"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='neaton-auto-products-manufacturing' AND approved AND profile IS NULL;
UPDATE companies SET description='New England Fabricated Metals, Inc. (NEFM) has operated from Leominster, Massachusetts since its founding in 1983. The company serves as a sheet metal fabrication and precision machining manufacturer for original equipment manufacturers and contract manufacturers across multiple sectors.

NEFM provides start-to-finish metal fabrication services including sheet metal forming, brake press bending, welding, machining, hardware insertion, mechanical assembly, and finishing. The facility also offers 3D/SLA printing, engineering support, prototyping, quality inspection, inventory management, and shipping. The company reports an annual output of approximately 200,000 pieces with a 99 percent product conformity rate.

The manufacturer works primarily with medical sterilization and medical technology companies, alongside other OEMs and contract manufacturers. A noted collaboration includes Sunrise Labs, where NEFM delivered a complex weldment on a tight schedule after a previous vendor failed.

NEFM differentiates itself through a combined team experience exceeding 400 years, a dedicated management presence on the production floor, and a quality management system certified to ISO 9001:2015. The company is also ITAR registered and emphasizes eliminating middlemen by handling projects from design through kitting.', certifications=ARRAY['ISO 9001:2015','ITAR']::text[], profile='{"capabilities": ["Sheet metal fabrication", "Precision machining", "Brake press forming", "Welding and post-weld machining", "Hardware insertion", "Mechanical assembly", "Welded assemblies and frames", "Material graining and finishing", "3D/SLA printing", "Engineering and design support", "Prototyping", "First article and AQL inspection", "Inventory management", "Shipping and fulfillment", "ITAR compliance"], "industries": ["Medical Sterilization", "Medical Technology"], "materials": [], "equipment": [], "volume": "Short-run to full-scale production; approximately 200,000 pieces annually", "lead_time": "", "tolerances": "", "built_on": ["Start-to-finish capabilities without a middleman", "Over 400 years of combined team experience", "Dedicated management team on the production floor", "ISO 9001:2015 certified quality management system", "ITAR registered"], "facts_used": ["Founded 1983 -> db, /about-us", "Headquarters Leominster, Massachusetts -> db", "Sheet metal fabrication and precision machining manufacturer -> /about-us, /", "Start-to-finish capabilities without a middleman -> /, /about-us", "400+ years combined team experience -> /", "Dedicated management team on floor -> /", "ISO 9001:2015 certified -> /, /quality", "ITAR registered -> /quality", "99% product conformity, ~200,000 pieces/year -> /quality", "Processes: sheet metal fabrication, brake press forming, welding, machining, hardware insertion, mechanical assembly, finishing, 3D/SLA printing, engineering, prototyping, quality inspection, inventory management, shipping -> /, /about-us, /quality", "Industries: Medical Sterilization, Medical Technology -> db", "Client example: Sunrise Labs -> /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='new-england-fabricated-metals' AND approved AND profile IS NULL;
UPDATE companies SET description='NuWay Electronics, based in Elk Grove Village, Illinois, was founded in 1975 as a provider of tape and reel packaging services.

The company offers cable assembly, tape and reel packaging (including surface mount, radial, and axial configurations), and component services such as lead forming and trimming, baking and dry packing, and sealing and coating. NuWay also manufactures UL- and FM-listed devices and operates with a quality system certified to ISO 9001:2015. Its workforce includes numerous employees with more than 20 years of tenure.

NuWay serves contract manufacturers and OEMs across sectors including clean energy, data centers, and stamped or machined electronic components. The company''s Chicago-area location provides access to major transportation networks.

NuWay emphasizes its long-standing experience, 100% inspection of tape and reel services, and a commitment to tailoring solutions to customer needs. The company cites its ISO 9001:2015 certification, UL and FM listings, and memberships in SMTA and IPC as foundations of its quality culture.', certifications=ARRAY['ISO 9001:2015','UL Listed','FM Listed']::text[], profile='{"capabilities": ["Cable Assembly", "Tape & Reel Packaging", "Surface Mount Tape & Reel", "Radial & Axial Tape & Reel", "Lead Forming and Trimming", "Baking & Dry Packing", "Sealing & Coating"], "industries": ["Contract Manufacturers (CMs)", "OEMs", "Clean Energy", "Data Centers", "Stamped/Machined Electronic Components"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ISO 9001:2015 certified since 1999", "Over 45 years of experience in tape and reel services", "100% inspection of tape and reel packaging", "UL and FM listed device manufacturer with regular inspection visits", "Long-tenured workforce (many employees 20+ years)"], "facts_used": ["Founded in 1975 -> /about", "Headquarters in Elk Grove Village, Illinois -> /about", "President Doug Hamilton -> /about", "ISO 9001:2015 certified since 1999 -> /about, /quality", "Services: Cable Assembly, Tape & Reel Packaging, Component Services -> /, /services", "Specific processes: Surface Mount Tape & Reel, Radial & Axial Tape & Reel, Lead Form/Trim, Baking & Dry Packing, Sealing & Coating -> /, /services", "Industries served: CMs and OEMs, Clean Energy, Data Centers, Stamped/Machined Electronic Components -> /, /about, /services", "UL and FM listed device manufacturer -> /quality", "100% inspection of tape and reel services -> /quality", "AQL Inspection Level II, AQL 1.0 for assemblies -> /quality", "Corporate Member of SMTA and IPC -> /about", "Employees with 20+ years tenure -> /about", "DUNS, Cage Code, Illinois Registration Number -> /about"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='nuway-electronics' AND approved AND profile IS NULL;
UPDATE companies SET description='O''Donnell Metal Fabricators, Inc. was founded in 1981 in Norristown, Pennsylvania, as a family-owned, American-made metal fabrication shop. The company began as a design and fabrication partner for OEMs, contractors, and plant managers, and has remained in the same location for over four decades.

The shop provides fully in-house metal fabrication, including CNC fiber laser cutting (up to 1-inch mild steel), CNC plasma cutting (up to 4-inch thick stainless, carbon steel, and aluminum), press brake forming with a 175-ton Cincinnati press brake (12-foot bed, 60-by-144-inch max sheet), shearing, sheet rolling (hot and cold), punch press work, welding (MIG, TIG, stick), and finishing such as powder coating and zinc plating. Production runs from single prototypes to full-scale volumes, with a stated laser tolerance of ±0.005 inch.

The company serves aerospace, automotive, military and defense, manufacturing, oil and energy, medical and pharmaceutical, facility maintenance, agriculture, food processing, construction, food service, hospitality, and commercial kitchen sectors. Customers include OEMs, engineers, architects, and contractors across Pennsylvania, New Jersey, Delaware, and Maryland.

O''Donnell differentiates itself through value engineering to reduce cost and improve function, a single-roof process that eliminates vendor handoffs, dedicated project managers who maintain visibility at every stage, and certifications that include AWS, NSF, and UL. The family-owned structure emphasizes competitive pricing, short lead times, and integrity throughout each build.', certifications=ARRAY['AWS Certified','NSF Certified','UL Listed']::text[], profile='{"capabilities": ["CNC Fiber Laser Cutting", "CNC Plasma Cutting", "CNC Laser Engraving", "Press Brake Forming", "Sheet Rolling (Hot and Cold)", "Punch Press Work", "Shearing", "Welding (MIG, TIG, Stick)", "Metal Finishing (Powder Coating, Zinc Plating)", "Field Installation", "Design (AutoCAD)", "Value Engineering", "Prototyping", "Production Runs"], "industries": ["Aerospace", "Automotive", "Military & Defense", "Manufacturing", "Oil & Energy", "Medical & Pharmaceutical", "Facility Maintenance", "Agriculture", "Food Processing", "Construction", "Food Service", "Hospitality", "Commercial Kitchens"], "materials": ["Stainless Steel", "Aluminum", "Mild Steel", "Carbon Steel"], "equipment": ["Cincinnati 175-ton Press Brake"], "volume": "Prototype to full production runs", "lead_time": "", "tolerances": "\u00b10.005 inch on laser work", "built_on": ["All design, fabrication, and finishing performed in-house", "Value engineering to optimize cost and performance", "Dedicated project managers with full project visibility", "AWS, NSF, and UL certified", "Family-owned and operated since 1981"], "facts_used": ["Founded 1981 in Norristown, PA -> db", "Family-owned, American-made business -> /about-us", "In-house design, fabrication, finishing -> /", "CNC fiber laser cutting up to 1-inch mild steel -> /", "CNC plasma cutting up to 4-inch thick stainless, carbon steel, aluminum -> /services", "175-ton Cincinnati press brake, 12-foot bed, 60x144 max sheet -> /", "Laser tolerance \u00b10.005 inch -> /", "Welding: MIG, TIG, Stick -> /services", "Sheet rolling hot and cold -> /services", "Punch press work -> /services", "Metal finishing: powder coating, zinc plating -> /services", "Field installation -> /services", "Industries: aerospace, automotive, military/defense, manufacturing, oil & energy, medical/pharmaceutical -> /", "Additional industries: facility maintenance, agriculture, food processing, construction, food service, hospitality, commercial kitchens -> /services", "Certifications: AWS, NSF, UL -> /, /services", "Value engineering offered -> /", "Dedicated project managers -> /", "Serves PA, NJ, DE, MD -> /services", "Prototype to full production runs -> /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='o-donnell-metal-fabricators-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='OE Solar is headquartered in Albuquerque, New Mexico. The company was founded in 2009 as Osceola Energy, Inc. with the original goal of installing solar across the state. It is a woman‑owned small business that rebranded to OE Solar as its focus expanded to enterprise‑level renewable energy solutions for both private and public sector clients.

The firm operates as a full‑service engineering, procurement, and construction (EPC) contractor for commercial solar photovoltaic systems, battery energy storage systems (BESS), EV charging infrastructure, solar carports, and microgrid installations. It also provides operations and maintenance, community solar development, and pre‑construction planning.

OE Solar serves commercial and industrial businesses, federal, state, and local government agencies, Tribal Nations, military installations, educational institutions, and hospitality venues. Named clients include Santa Ana Casino, Santa Ana Golf Club, Albuquerque Public Schools, and the Picuris Pueblo — for whom the company built New Mexico’s first community solar project.

The company emphasizes its GSA‑approved, woman‑owned small business status, NABCEP certification, and Tesla and ChargePoint certified installers as differentiators. It also highlights deep expertise in government energy policy, established relationships with regulators and policymakers, and a founding philosophy built on honesty, craftsmanship, and ownership.', certifications=ARRAY['GSA Approved','NABCEP Certified','Tesla Certified','ChargePoint Certified']::text[], profile='{"capabilities": ["Engineering, procurement, and construction (EPC)", "Solar PV system installation", "Battery energy storage system (BESS) installation", "EV charging station installation (Level 2, Tesla, ChargePoint)", "Solar carport installation", "Microgrid system design and installation", "Operations and maintenance (O&M)", "Community solar development", "Pre\u2011construction planning and engineering", "Government contracting", "Commercial and industrial solar projects", "Federal tax credit consulting (ITC, PTC)"], "industries": ["Commercial and industrial", "Government (federal, state, local)", "Tribal Nations", "Military installations", "Education", "Hospitality", "Community solar", "Electric vehicle charging infrastructure"], "materials": ["Solar PV modules", "Inverters", "Racking", "Wiring", "Battery energy storage systems", "EV charging stations (Level 2)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["GSA\u2011approved woman\u2011owned small business", "NABCEP\u2011certified company", "Tesla & ChargePoint certified installers", "First community solar project in New Mexico (Picuris Pueblo)", "Expert knowledge of government energy policy and regulator relationships"], "facts_used": ["Founded 2009 as Osceola Energy, Inc. -> db", "Headquarters Albuquerque, New Mexico -> db", "Woman\u2011owned certification -> db", "Mission Driven since 2009, 17 years in business -> /", "6.8 MW solar installed, 2,123 clients -> /", "Services: EPC, solar PV, BESS, EV charging, carports, microgrids, O&M, community solar -> /", "Clients: Santa Ana Casino, Santa Ana Golf Club, Albuquerque Public Schools, Picuris Pueblo -> /", "Industries served: commercial/industrial, government, Tribal Nations, military, education, hospitality -> /", "GSA approved, woman\u2011owned small business -> /", "NABCEP\u2011certified company -> /", "Tesla & ChargePoint certified installers -> /", "First community solar project in NM (Picuris Pueblo) -> /", "Expert knowledge of government energy policy, relationships with policymakers -> /", "Founding principles: honesty, craftsmanship, ownership -> /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='oe-solar' AND approved AND profile IS NULL;
UPDATE companies SET description='Obertron Electronic Manufacturing has operated from Manchester, Michigan since its founding in 1986. The company provides PCB assembly services from a single Midwestern facility, emphasizing skilled craftsmanship and responsive service.

The shop specializes in medium-volume, high-mix PCBA assembly, combining automated surface-mount placement (including 01005, QFN, BGA, and fine-pitch components) with through-hole selective and hand soldering. It offers full turnkey support—component procurement, inventory holding, conformal coating, potting, box build, and mechanical assembly—alongside PCB fabrication sourcing for boards up to 36 layers with trace/space tolerances of 0.003″ outer and 0.002″ inner. All work is performed to IPC-A-610 Class 2/3 and ISO 9001:2015 standards, with 100% visual inspection and 3D AOI coverage.

Customers span LED lighting, service industries (commercial, hospitality, healthcare), test and measurement, instrumentation, industrial equipment, medical and health devices, aerospace and automotive (including EV), agriculture and industrial automation, commercial and recreational electronics, and R&D prototypes.

Obertron differentiates itself through lean manufacturing, ongoing staff training, flexible production scheduling, and a standard 5–6 week lead time. A one-year labor warranty and transparent quoting reinforce its focus on dependable partnerships.', certifications=ARRAY['ISO 9001:2015','IPC-A-610','RoHS']::text[], profile='{"capabilities": ["Surface mount technology (SMT) assembly", "Through-hole technology (THT) assembly", "Selective soldering", "Hand soldering", "Automated optical inspection (AOI) with 01005 capability", "Visual inspection (100% of product)", "Functional testing (with customer-supplied fixtures)", "Component sourcing and procurement", "Inventory holding and flexible release scheduling", "Conformal coating and potting", "Box build and mechanical assembly", "PCB fabrication support (materials, layer counts, finishes)", "Turnkey manufacturing services", "Design support", "Programming and testing with customer-supplied resources", "Wire harness assembly", "RoHS-compliant production", "Water-soluble and no-clean process options", "Custom reflow profiling", "IPC-A-610 Class 2 and Class 3 manufacturing", "1-year labor warranty"], "industries": ["LED Lighting", "Service Industries (commercial, hospitality, healthcare)", "Testing & Measurements", "Instrumentation & Gauging", "Industrial Equipment", "Medical & Health", "Aerospace & Automotive", "Agriculture & Industrial", "Commercial & Recreational", "Research & Development"], "materials": ["FR-4", "High-Tg FR-4", "Aluminum", "Polyimide", "Advanced dielectric materials", "ENIG", "OSP", "Lead-free HASL", "Copper (1/3 oz to 6 oz)"], "equipment": [], "volume": "Prototype to full-scale production; medium-volume, high-mix", "lead_time": "5\u20136 weeks standard lead time", "tolerances": "Trace/spacing: 0.003\u2033 outer, 0.002\u2033 inner; mechanical drills \u22640.008\u2033", "built_on": ["Medium-volume, high-mix PCBA assembly", "100% visual inspection with 3D AOI down to 01005 components", "Full turnkey sourci