UPDATE companies SET description='PB Metal Fab, an employee-owned metal fabrication job shop, was founded in 2010 in Ipswich, South Dakota, near the regional hub of Aberdeen. The company began with a focus on providing high-quality parts and fabrication services across the Midwestern states.

Operating from a 110,000-square-foot facility built in phases—a 40,000-square-foot plant in 2012 and a 67,000-square-foot expansion in 2024—the shop runs flat-sheet and tube lasers, a 150-metric-ton press brake, 20-by-40-inch machining centers, an 8-inch four-roll plate roller, in-house shot blasting, and automated material storage. Its service list covers fiber laser cutting, water jet cutting, CNC forming, machining, plate rolling, welding (aluminum, stainless, mild steel), shot blasting, material sales, and CAD/CAM support.

The company serves a diverse customer base throughout North America, though specific industry sectors are not publicly detailed. Its capabilities are geared toward clients needing precision cutting, forming, and post-processing of metals and non-metals such as marble and granite.

PB Metal Fab emphasizes a customer-driven approach, citing prompt, cost-effective delivery and a single-source workflow from cutting through finishing as key differentiators.', certifications=ARRAY['ISO 9001']::text[], profile='{"capabilities": ["Fiber laser cutting (flat sheet)", "Tube laser cutting", "Water jet cutting", "CNC forming (press brake)", "CNC machining", "Plate rolling", "Shot blasting", "Welding (aluminum, stainless steel, mild steel)", "Material sales (steel sheeting)", "CAD/CAM file acceptance and 3D software support"], "industries": [], "materials": ["Aluminum", "Mild steel", "Stainless steel", "Copper", "Tungsten", "Titanium", "Brass", "Bronze", "Zirconium", "Marble", "Granite"], "equipment": ["Flat-sheet laser cutting systems", "Tube laser cutting systems", "150 metric ton (165 US ton) 10'' press brake", "20\" x 40\" X,Y machining centers", "Flex arm tapping arm", "8\" 4-roll plate rolling machine", "In-house steel shot blasting system", "Automated material storage system"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Employee-owned and operated structure", "110,000 sq ft facility with automated material storage", "All major processes (laser, water jet, forming, machining, welding, finishing) in-house", "150-ton press brake and 20x40 machining centers for heavy forming and machining", "Commitment to prompt, cost-effective delivery"], "facts_used": ["Founded 2010 -> db", "Employee-owned -> db (description)", "Headquarters Ipswich, SD -> db (hq_city, hq_state_label)", "Facility size 110,000 sq ft (2012 + 2024) -> db (description)", "Equipment: flat-sheet lasers, tube lasers, press brake, machining centers, plate rolling, shot blasting, automated storage -> db (description) and / (homepage)", "Processes: fiber laser, water jet, CNC forming, machining, plate rolling, welding, shot blasting, material sales, CAD/CAM -> / (homepage)", "Materials: aluminum, mild steel, stainless steel, copper, tungsten, titanium, brass, bronze, zirconium, marble, granite -> / (homepage)", "Certification ISO 9001 -> db (certifications)", "Customer-driven focus -> db (description) and / (homepage)", "Located near Aberdeen, SD -> / (homepage)"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='pb-metal' AND approved AND profile IS NULL;
UPDATE companies SET description='PICO Manufacturing Sales Corporation was founded in 1931 in New York, New York, and has remained family-owned and operated since its inception. In 1958, Ira Litt joined the company and established its headquarters in the Empire State Building, situating the business in the heart of the Garment District.

The company designs, develops, and manufactures a full range of underwear and sleepwear — including boxer briefs, woven boxers, base layers, flame-resistant children''s sleepwear, and active lifestyle apparel — for men, women, and children. Operations span product design, yarn and fabric development, merchandising, and package design. Production was relocated to Dayton, Tennessee in 1973, and the company handles orders ranging from 500 to 500,000 units.

PICO serves the apparel industry as a private-label manufacturer for department stores, mass retailers, and specialty stores, and acts as a strategic license partner for major brands in the underwear and sleepwear categories.

The company emphasizes its vertically integrated approach — developing proprietary yarns and fabrics, maintaining trend-focused design, and offering dedicated customer service throughout the process. It also highlights a sustainability commitment, holding BCI, OEKO-TEX, WRAP, Sedex, and CTPAT certifications, with a goal of 80% renewable energy use by 2021.', certifications=ARRAY['OEKO-TEX','BCI','WRAP','Sedex','CTPAT']::text[], profile='{"capabilities": ["Customer service", "Product design", "Yarn development", "Fabric development", "Merchandising", "Package design", "Sustainable production", "Private label manufacturing", "Brand licensing", "Quality assurance", "Order fulfillment"], "industries": ["Apparel manufacturing", "Private label manufacturing", "Brand licensing", "Department stores", "Mass retail", "Specialty retail"], "materials": [], "equipment": [], "volume": "500 to 500,000 units", "lead_time": "", "tolerances": "", "built_on": ["Proprietary yarn and fabric development", "Trend-driven design with consumer focus", "Dedicated customer service at every step", "Multiple sustainability certifications (BCI, OEKO-TEX, WRAP, Sedex, CTPAT)", "Flexible order fulfillment from 500 to 500,000 units"], "facts_used": ["Founded 1931, family-owned -> db, /", "Ira Litt joined 1958, headquarters in Empire State Building -> /", "Production moved to Dayton, Tennessee 1973 -> /", "Product range: underwear, sleepwear, base layers, FR sleepwear, active lifestyle -> /", "Processes: design, yarn/fabric development, merchandising, package design, sustainable production -> /", "Private label for department stores, mass retailers, specialty stores -> /", "License partner for major brands -> /", "Certifications: BCI, OEKO-TEX, WRAP, Sedex, CTPAT -> /", "Sustainability goal: 80% renewable energy by 2021 -> /", "Order volume range 500-500,000 units -> /", "Customer service emphasis -> /", "Headquarters in Garment District, New York, NY -> db, /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='pico-manufacturing-sales-corporation' AND approved AND profile IS NULL;
UPDATE companies SET description='Premold Corp was founded in 1995 by Ken Schweitz in Oconomowoc, Wisconsin. The privately owned company operates two facilities in Oconomowoc and a third in Monterrey, Mexico.

The company specializes in reaction injection molding, producing rigid polyurethane parts for low-volume and prototype applications. Its capabilities span in-house tool making with CNC-machined aluminum molds, cast urethane and stereolithography prototyping, short-run production with just-in-time delivery, finish painting using Sherwin Williams Polane coatings, UL-recognized EMI shielding, silk-screen and pad-print graphics, and full assembly including procurement and sub-assembly. The RIM process allows complex geometries, varying wall thicknesses without sink marks, and molded-in features that eliminate secondary machining.

Premold serves a range of industries with a focus on medical and laboratory instrumentation, supplying molded housings, bezels, and skins. Customers include medical device manufacturers requiring custom low-volume polyurethane components.

The company differentiates itself through a single-source model that integrates tooling, molding, finishing, and assembly under one roof, reducing lead times and enabling design-for-manufacture collaboration from prototype through production.', certifications=ARRAY['ISO 9001:2015','UL Recognized','CTPAT','IMMEX','OEA Mexico']::text[], profile='{"capabilities": ["Reaction Injection Molding (RIM)", "High Pressure Injection Molding", "Tool Making (CNC machining of aluminum molds)", "Prototyping (cast urethane, stereolithography)", "Short Run Production", "Finish Painting (wet spray)", "EMI Painting (EMI shielding coatings)", "Graphics (silk-screen, pad-print)", "Assembly (sourcing, procurement, sub-assembly, full assembly)", "Encapsulation of metal, plastics, and electronics", "Molded-in features (no secondary machining)", "Design for Manufacture (DFM) consultation"], "industries": ["Medical", "Laboratory Instruments"], "materials": ["Rigid polyurethane (RIM)", "Cast urethane (prototyping)", "Aluminum (tooling)", "Silicone (prototype molds)", "Sherwin Williams Polane paints", "EMI shielding coatings"], "equipment": ["CNC machining centers", "Stereolithography (SLA) machines", "Wet spray painting equipment"], "volume": "Prototype to low-volume production (thousands of cycles)", "lead_time": "Short lead times for prototypes; just-in-time delivery for production", "tolerances": "Tight tolerances", "built_on": ["In-house tool making with full CNC capabilities for aluminum molds", "Rapid prototyping via cast urethane and stereolithography (SLA)", "Short-run production with just-in-time delivery", "In-house finish painting with Sherwin Williams Polane coatings", "UL-recognized EMI shielding coatings applied to molded parts"], "facts_used": ["Founded 1995 by Ken Schweitz -> db", "Headquarters Oconomowoc, Wisconsin -> db", "Privately owned, led by President Ximena Schweitz -> /", "Two facilities in Oconomowoc, one in Monterrey, Mexico -> /", "Specializes in Reaction Injection Molding (RIM) for rigid polyurethane parts -> /", "In-house tool making with CNC-machined aluminum molds -> /services", "Prototyping via cast urethane and stereolithography (SLA) -> /services", "Short-run production with just-in-time delivery -> /services", "Finish painting with Sherwin Williams Polane coatings -> /services", "UL-recognized EMI shielding coatings -> /services", "Silk-screen and pad-print graphics -> /services", "Assembly including sourcing, procurement, sub-assembly -> /services", "Focus on medical and laboratory instrumentation -> /", "Molded housings, bezels, skins for medical industries -> /", "Certifications: ISO 9001:2015 (USA and Mexico), UL Recognized, CTPAT, IMMEX, OEA Mexico -> /", "Materials: rigid polyurethane, cast urethane, aluminum tooling, silicone molds -> /, /services", "Volume: prototype to thousands of cycles -> /services", "Lead times: short for prototypes, JIT for production -> /services", "Tolerances: tight tolerances -> /services"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='premold-corp' AND approved AND profile IS NULL;
UPDATE companies SET description='Pacific Auto Company, operating as Pacific Best Inc., was established in 1983 in Paramount, California, within the Los Angeles metropolitan area. The company began as a warehouse distributor of automotive collision body parts and cooling products, serving the Southern California repair market.

Today, Pacific Auto Company maintains six distribution centers across Southern California, supported by over nine warehouses and a dedicated delivery fleet. The company stocks a complete line of aftermarket collision parts — including radiators, condensers, fan assemblies, intercoolers, external oil coolers, cabin air filters, door mirrors, and lighting — all certified to meet OEM replacement standards. Its lighting products comply with DOT/SAE regulations, and it carries an extensive selection of CAPA- and NSF-certified body parts. The firm reports over 30 million parts sold since inception.

Its coverage area spans eight Southern California counties — Santa Barbara, Kern, Ventura, Los Angeles, San Bernardino, Riverside, and Orange — with guaranteed 24-hour delivery on business days.

Pacific Auto Company differentiates itself through a no-contract, no-buy-in account structure, volume discount programs, and a procurement team that uses data analytics to maintain high fill rates. The company emphasizes competitive pricing on every order and a quality administration system designed to streamline ordering and same-day dispatch.', certifications=ARRAY['ISO 9001']::text[], profile='{"capabilities": ["Warehouse distribution of automotive aftermarket parts", "Collision body parts distribution", "Cooling system components distribution", "CAPA/NSF certified parts sourcing", "DOT/SAE compliant lighting supply", "24-hour delivery service (Southern California)", "Inventory management and procurement analytics", "Quality administration and distribution management", "Same-day order dispatch", "Volume discount programs for collision repair businesses"], "industries": ["Automotive repair", "Collision repair", "Auto parts retail", "Auto parts distribution", "Auto body shops", "Auto restoration", "General repair shops", "Dealerships", "Wrecking yards", "Insurance providers", "Estimation services", "Jobbers"], "materials": [], "equipment": [], "volume": "Over 30 million parts sold", "lead_time": "24-hour delivery within Southern California coverage area; same-day dispatch for orders placed during business hours", "tolerances": "", "built_on": ["24-hour delivery within eight-county Southern California coverage area", "Over nine warehouses and six distribution centers in Southern California", "CAPA- and NSF-certified automotive body parts", "DOT/SAE-compliant lighting products", "No buy-in or contract required for account setup; volume discounts available"], "facts_used": ["Founded in 1983 -> db, /about-us", "Headquartered in Paramount, California -> db, /about-us", "ISO 9001 certified -> db, /about-us", "Warehouse distributor of automotive collision body parts and cooling products -> /about-us", "Six distribution centers in Southern California covering eight counties -> /about-us", "Over nine warehouses in Southern California -> /about-us", "24-hour delivery on business days within coverage area -> /about-us", "Large fleet of delivery vehicles -> /about-us", "Over 30 million parts sold -> /", "CAPA and NSF certified automotive body parts -> /about-us", "DOT/SAE compliant lighting -> /about-us", "Serves collision repair shops, body shops, jobbers, insurance providers, estimation services, auto parts retailers, dealerships, restoration specialists, wrecking yards -> /about-us", "No buy-in or contract required for account setup -> /about-us", "Volume discounts for collision repair businesses -> /about-us", "Competitive pricing on every order -> /about-us", "Quality administration and distribution management system -> /about-us", "Manufacturing partners ISO/TS16949 certified -> db", "Products meet OEM replacement part standards -> /about-us"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='pacific-auto-company' AND approved AND profile IS NULL;
UPDATE companies SET description='Pacific Packaging Products, Inc. – South operates from Nashville, Tennessee, where the company was founded in 1952 as a family‑owned independent business.

The company provides a full range of packaging products, equipment, and automation systems, backed by in‑house converting capabilities that include slitting, rewinding, die cutting, sheeting, flexographic label and bag printing, and custom tape printing. It also offers packaging design, engineering and testing, kitting and contract packaging, and fulfillment services for direct‑mail operations. Pacific’s infrastructure spans multiple U.S. locations, supporting national accounts with inventory management and lean supply‑chain programs.

Customers come from food and beverage, military and defense, retail point‑of‑purchase, general manufacturing, healthcare and pharmaceuticals, automotive, and fulfillment/direct‑mail sectors. The company also specializes in cold‑chain packaging for seafood and perishable goods, supplying insulated shippers, refrigerants, and temperature‑monitoring devices.

Pacific positions itself as a hybrid partner that combines the reach and leverage of a large multinational supplier with the agility and responsiveness of a family‑owned independent company. Its stated differentiation lies in end‑to‑end integration—from concept and prototyping through converting, printing, automation, and final pack‑out—designed to reduce handling steps and total supply‑chain cost.', certifications=ARRAY['ISO 9001']::text[], profile='{"capabilities": ["Kitting and contract packaging", "Tape printing", "Label and bag printing", "Slitting and rewinding", "Die cutting and sheeting", "Packaging design", "Engineering and testing", "Converting and manufacturing", "Fulfillment and direct mail"], "industries": ["Food and beverage", "Military and defense", "Retail point of purchase", "Manufacturing and industrial", "Healthcare and pharmaceuticals", "Automotive", "Fulfillment and direct mail", "Cold chain and seafood"], "materials": ["Stretch film", "Shrink film", "Packaging tapes and adhesives", "Poly bags and flexible films", "Strapping and banding", "Protective foam, bubble, and void fill", "Corrugated boxes and containers", "Thermoformed plastic products", "Paperboard and industrial paper", "Labels and printed tape", "Insulated shippers", "Refrigerants and gel packs", "Wax-coated boxes", "Plastic corrugated", "Folding cartons", "Temperature monitors"], "equipment": ["Case erecting and sealing systems", "Pallet wrapping machines", "Shrink wrapping equipment", "Robotics", "Automated bagging systems", "Protective packaging equipment", "Labeling and identification systems", "Strapping and securing equipment", "Material handling equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Coast-to-coast inventory and distribution network", "Family-owned independent structure with national reach", "In-house converting, printing, and testing capabilities", "Lean supply chain optimization and national account management", "Cold chain packaging expertise for perishable goods"], "facts_used": ["Founded in 1952 -> db, /about-us", "Headquarters Nashville, Tennessee -> db", "Family-owned independent company -> /about-us", "ISO 9001 certification -> db", "Capabilities: kitting, contract packaging, tape printing, label and bag printing, slitting, rewinding, die cutting, sheeting, packaging design, engineering and testing, converting and manufacturing, fulfillment and direct mail -> /capabilities", "Industries served: food and beverage, military and defense, retail point of purchase, manufacturing, healthcare, automotive, fulfillment, cold chain -> / (homepage) industries list", "Equipment: case erecting, pallet wrapping, shrink wrapping, robotics, automated bagging, protective packaging, labeling, strapping, material handling -> / (homepage) equipment list", "Materials: stretch film, shrink film, tapes, poly bags, strapping, foam, corrugated, thermoformed plastics, paperboard, labels, insulated shippers, refrigerants, wax boxes, plastic corrugated, folding cartons, temperature monitors -> / (homepage) products list", "Coast-to-coast infrastructure and national accounts -> /about-us", "Lean supply chain optimization -> /capabilities", "Cold chain packaging expertise -> / (homepage) seafood section"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='pacific-packaging-products-inc-south' AND approved AND profile IS NULL;
UPDATE companies SET description='Peace River Packing Company operates from Fort Meade, Florida. Founded in 1928 by a group of local citrus growers who pooled resources to build their own packinghouse, the business has remained family-owned and operated. It later became an agricultural cooperative and a member of Florida’s Natural Growers in 1970.

The company manages and harvests more than 2,000 acres of citrus groves across Polk, Highlands, and Hillsborough counties, and packs oranges, tangerines, and grapefruit. Its facility includes high-speed electronic fruit graders, automated bagging machines, and a large multilevel cooler. With over 130 employees, it is the largest private employer in Fort Meade and ranks among the top 20 fresh citrus packinghouses in Florida by production volume.

Peace River serves the fresh citrus market, supplying fruit to customers globally through the Florida’s Natural Growers cooperative. Its primary industries are citrus production, fresh fruit packing, and agricultural cooperatives.', certifications=ARRAY['PrimusGFS']::text[], profile='{"capabilities": ["Citrus Grove Management", "Harvesting", "Packing Fresh Fruit"], "industries": ["Citrus Production", "Fresh Fruit Packing", "Agricultural Cooperatives"], "materials": ["Oranges", "Tangerines", "Grapefruit"], "equipment": ["High-speed electronic fruit graders", "Automated bagging machines", "Massive multilevel cooler"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned and operated since 1928", "Agricultural cooperative member of Florida\u2019s Natural Growers since 1970", "Manages and harvests over 2,000 acres of citrus groves", "Largest private employer in Fort Meade", "Top 20 fresh citrus packinghouse in Florida by production"], "facts_used": ["Founded 1928 by group of Fort Meade citrus growers -> /about-us", "Family-owned and operated -> /about-us, db", "Headquarters Fort Meade, Florida -> db, /about-us", "Member of Florida''s Natural Growers since 1970 -> /about-us", "Agricultural cooperative -> /about-us", "Manages and harvests over 2,000 acres in Polk, Highlands, Hillsborough counties -> /about-us", "Packs oranges, tangerines, grapefruit -> /about-us", "Top 20 fresh citrus packinghouses in Florida by production -> /about-us", "Largest private employer in Fort Meade with over 130 employees -> /about-us, db", "Facility includes high-speed electronic fruit graders, automated bagging machines, massive multilevel cooler -> /about-us", "Certification: PrimusGFS -> db", "Capabilities: Citrus Grove Management, Harvesting, Packing Fresh Fruit -> db"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null,