ial_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='pennsylvania-transformer-technology-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Phase Electronics is a privately owned, family-run electronics manufacturer based in Rockville, Maryland.

Operating from an owner-occupied 26,000-square-foot facility, Phase Electronics provides a range of electronic manufacturing services including rapid prototyping, medium-volume production, surface-mount and through-hole PCB assembly, electromechanical box builds, cable assemblies, rework, conformal coating, X-ray inspection, and programming and testing. The plant is fully ESD-safe and equipped with modern machinery, including automated optical inspection systems. The staff consists of long-tenured, IPC-trained employees, many with 15-plus years at the company.

The company serves customers in the commercial, military, medical, and automotive sectors, delivering assemblies built to IPC-A-610 Class 2 standards with Class 3 available on request. All personnel handling assemblies are trained to J-STD-001 with the space addendum.

Phase Electronics emphasizes a direct line to the manufacturing floor for real-time issue resolution, 100 percent inspection via automated optical inspection and hand checks, and compliance with J-STD-001 including the space addendum. The firm is ITAR registered, holds ISO 9001:2015 certification, and is SAM registered, aiming to provide quality manufacturing at reasonable prices within customer time constraints.', certifications=ARRAY['ISO 9001:2015','ITAR Registered','RoHS','J-STD-001 with Space Addendum','IPC-A-610','SAM Registered']::text[], profile='{"capabilities": ["Rapid prototyping", "Medium volume production", "Surface mount technology (SMT) assembly", "Through-hole PCB assembly", "Electromechanical box build", "Cable assembly", "Rework and repair services", "Conformal coating", "X-ray inspection", "Programming and testing", "Component removal and replacement"], "industries": ["Commercial", "Military", "Medical", "Automotive"], "materials": [], "equipment": ["Automated optical inspection (AOI) machines", "X-ray inspection equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["100% inspection via automated optical inspection (AOI) and hand checks", "Direct line to manufacturing floor with real-time communication", "IPC-A-610 Class 2/3 and J-STD-001 with space addendum compliance", "Owner-occupied 26,000+ sq ft facility with long-tenured staff", "ITAR registered, ISO 9001:2015, RoHS, and SAM registered"], "facts_used": ["Founded in 1984 by David Regnier -> /about", "Privately owned small family business -> /about", "Owner-occupied 26,000+ sq ft facility -> /about", "Long-term dedicated employees (15+ years) -> /about", "IPC trained staff -> /about", "Certifications: ISO 9001:2015, J-STD-001 + Space Addendum, IPC-A-610, ITAR Registered, RoHS, SAM Registered -> /about", "Industries served: commercial, military, medical, automotive -> /about", "Services: rapid prototyping, medium volume production, SMT thru hole, electromechanical box build, rework, cables, programming/testing, conformal coating, X-ray diagnostics, remove/replace components -> /services", "100% inspection by hand or AOI -> /", "Direct line to manufacturing floor with real-time communication -> /", "ESD safe work areas and latest machinery -> /", "IPC-A-610 Class 2/3 and J-STD-001 with space addendum -> /", "Goal: quality manufacturing at reasonable prices within customer time constraints -> /about"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='phase-electronics' AND approved AND profile IS NULL;
UPDATE companies SET description='The company was established in 2007 as a custom injection and blow molding provider.

It specializes in short to long production runs of plastic components, offering injection molding, blow molding, design assistance, 3D prototyping, mold design and making, secondary operations, and inventory management programs such as just-in-time, dock-to-stock, and min-max. The 34,000-square-foot environmentally controlled facility includes docks, silos, overhead cranes, and modern equipment to support complete custom services from design through final qualified thermoplastic products. The company also provides tooling services and production support ranging from prototyping to mass manufacturing.

Plasticology produces parts in materials including LDPE, rigid PVC, PETG, ABS and high-impact grades, acrylic, and polypropylene, serving original equipment manufacturers and other customers requiring custom thermoplastic components.

The company states its focus is on employees, customers, quality, service, competitive pricing, efficiency and cost-reduction improvements, and community. Its mission emphasizes developing long-term relationships to help customers maintain and improve their performance through coordinated teamwork. Plasticology maintains ISO 9001:2015 certification as part of its quality commitment.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Injection Molding", "Blow Molding", "Design Assistance", "3D Prototyping", "Mold Design", "Mold Making", "Secondary Operations", "Inventory Management (JIT/Dock-to-Stock/Min-Max)", "Tooling Services"], "industries": [], "materials": ["LDPE", "Rigid PVC", "PETG", "ABS", "High Impact Polystyrene", "Acrylic", "Polypropylene"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Complete custom services from design through final qualified thermoplastic products", "Environmentally controlled 34,000 sq ft facility with docks, silos, and overhead cranes", "Inventory management programs including JIT, dock-to-stock, and min-max", "ISO 9001:2015 certified quality system", "Focus on employees, customers, quality, service, competitive pricing, efficiency, and community"], "facts_used": ["Location: Hawarden, Iowa -> db", "Founded: 2007 -> db, /about", "Services: injection molding, blow molding, design assistance, 3D prototypes, mold design/making, secondary operations, inventory management -> description, /", "Facility: 34,000 sq ft environmentally controlled with docks, silos, overhead cranes -> /about", "Certification: ISO 9001:2015 -> /, db", "Materials: LDPE, Rigid PVC, PETG, ABS & High Impact, Acrylic, PP -> /", "Mission/focus: employees, customers, quality, service, competitive prices, efficiency/cost reduction, community -> /", "Mission statement: develop long-term relationships to help customers maintain and improve performance -> /about", "Company type: LLC -> name", "Tooling services and production support -> /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='plasticology-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Plastics Advanced Research, operating as PART Inc., has been based in Clover, South Carolina since its founding in 1978. Dennis Denton established the company with a vision to provide unparalleled quality and service in plastic injection molding.

The company provides custom plastic injection molding services from initial concept through finished production. Its capabilities include custom molding, rapid prototyping with fast turnaround times, and both low-volume and high-volume production runs.

PART Inc. serves diverse industries with plastic components, though the company does not specify individual sectors in its public materials. Customers range from those needing prototype validation to full-scale production partners.

The operation is ISO 9001:2015 certified by Bureau Veritas, and leadership emphasizes integrity, innovation, and collaboration as core values.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Custom Injection Molding", "Rapid Prototyping", "Low-Volume Production Molding", "High-Volume Production Molding", "Product Concept and Design Development"], "industries": [], "materials": [], "equipment": [], "volume": "Low-volume to high-volume production", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded in 1978 by Dennis Denton -> /about", "Current leaders Kacy and Brad Denton (brothers) with over 60 years combined experience -> /about", "Headquarters in Clover, SC -> /about", "ISO 9001:2015 certified by Bureau Veritas -> /about", "Offers custom molding, prototyping, and production services -> /services", "Goal to be one of the best, not the largest -> /about and /", "99.9% satisfaction rating for quality and on-time delivery since 2000 -> / and /services", "State-of-the-art facility with latest technology -> /about", "Family-owned business (brothers following father) -> /about", "Over 40 years experience in concept, design, development of plastic products -> / and /about", "Low-volume to high-volume production capabilities -> /services", "Fast turnaround times for prototyping -> /services"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='plastics-advanced-research' AND approved AND profile IS NULL;
UPDATE companies SET description='Polar Wire Products was founded in 1991 in Anchorage, Alaska, as a family-owned business. From its humble beginnings in Alaska, the company expanded to key locations in the lower 48 states while maintaining its headquarters and manufacturing in Anchorage.

The company manufactures premium industrial-grade wire, most notably its flagship Arctic Ultraflex Blue® and Arctic Superflex Blue® lines, which are rated for continuous operation from -55°C to 105°C and use 100% copper conductors with no aluminum. In addition to wire manufacturing, Polar Wire provides custom cable assembly services built to IPC/WHMA-A-620 Class 3 standards, wholesale distribution of solderless terminals, compression and mechanical lugs, heat shrink, and other wiring control products and tools. Its facilities offer engineering services and technical review, precision cutting and stripping, and high-quality crimping, with capacity ranging from rapid prototyping to large-scale production. Thousands of fittings and products are stocked for quick turnaround.

Polar Wire serves a broad customer base that includes the general public, government agencies, OEMs, stocking distributors, and fleet accounts. Its products are used in renewable energy, telecommunications, automotive, fleet, commercial, industrial, and recreational applications. Finished assemblies appear as battery cables, jumper cables, extension cords, shore power and generator leads, and stage and lighting cords.

The company emphasizes its hands-on control of every stage from design to assembly, citing superior quality, exceptional customer service, and competitive pricing as differentiators. Its wire has been proven in extreme environments from Alaska''s North Slope to Antarctica, and the team carries over 200 years of combined industry experience. Polar Wire aims for long-term, mutually beneficial partnerships and offers private-label/OEM manufacturing with custom configurations, colors, striping, and print legends.', certifications=ARRAY['UL Listed','RoHS']::text[], profile='{"capabilities": ["Wire manufacturing (single/multi-conductor, cold-weather flexible)", "Custom cable assembly", "Wholesale distribution of wiring components (terminals, lugs, heat shrink, tools)", "Private label/OEM manufacturing", "Engineering services & technical review", "Precision cutting & stripping", "Crimping", "IPC/WHMA-A-620 Class 3 assembly", "Rapid prototyping to large-scale production", "Custom wire configurations (colors, striping, print legends)"], "industries": ["Renewable Energy", "Telecommunications", "Automotive", "Fleet", "Commercial", "Industrial", "Government", "OEM", "Distribution", "Recreational"], "materials": ["Copper", "EPDM"], "equipment": [], "volume": "Rapid prototyping to large-scale production", "lead_time": "", "tolerances": "", "built_on": ["Wire rated -55\u00b0C to 105\u00b0C, proven in extreme environments", "100% copper conductor, no aluminum used", "IPC/WHMA-A-620 Class 3 assembly capabilities", "Private label/OEM manufacturing with custom configurations", "Family-owned with 35+ years in business and 200+ years combined personnel experience"], "facts_used": ["Founded in 1991 in Anchorage, Alaska -> db", "Family-owned business for over 35 years -> /about-us", "Premier product lines Arctic Ultraflex Blue and Arctic Superflex Blue -> /", "Wire rated -55\u00b0C to 105\u00b0C -> /, /about-us", "100% copper conductor, no aluminum -> /", "Custom cable assembly services with IPC/WHMA-A-620 Class 3 capabilities -> capabilities, /", "Wholesale supplier of solderless terminals, lugs, heat shrink, tools -> /", "Private label/OEM manufacturing capabilities -> /", "Engineering services & technical review -> /", "Precision cutting & stripping -> /", "Crimping -> /", "Serves Renewable Energy, Telecommunications, Automotive, Fleet, Commercial, Industrial, Government, OEM, Distribution -> industries_served, /", "Products used in battery cables, jumper cables, extension cords, shore power/generator leads, stage and lighting cords -> /about-us", "Personnel with 200+ years combined industry experience -> /", "Free shipping on online orders over $150 -> /", "Rapid prototyping to large-scale production -> /", "Custom wire configurations, colors, striping, print legends -> /"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='polar-wire-products' AND approved AND profile IS NULL;
UPDATE companies SET description='Polymer Packaging, Inc. was founded in 1973 in North Canton, Ohio. The company began as a specialist in bakery packaging and has since expanded into a manufacturer, converter, and distributor of flexible, protective, and general-purpose packaging. Ownership details and founder names are not publicly disclosed.

The company operates facilities in North Canton and Allendale, producing a range of packaging solutions including stand-up pouches, rollstock, foam, bubble, and spunbond products, as well as retention and suspension packaging. It also supplies commodity items such as tape, stretch film, labels, ribbons, strapping, and corner boards. Specific production volumes, headcount, and facility square footage are not disclosed.

Polymer Packaging serves the food, beverage, bakery, industrial, specialty manufacturing, automotive, aerospace, medical, and pharmaceutical sectors. Its customer base includes companies requiring engineered flexible packaging as well as low-cost commodity packaging.

The company states its mission is to be the provider of engineered flexible packaging solutions and the low-cost supplier of commodity packaging products. It emphasizes a collaborative approach that delivers fast, effective solutions for demanding applications.', certifications=ARRAY['ISO 9001','ISO 4001','GDP Certified']::text[], profile='{"capabilities": ["Flexible packaging manufacturing", "Protective packaging manufacturing", "Bakery packaging", "General commodity packaging distribution", "Converting", "Distribution", "Retention and suspension packaging", "Stand-up pouch production", "Rollstock production", "Foam packaging", "Bubble packaging", "Spunbond packaging", "Tape and stretch film supply", "Label and ribbon supply", "Strapping supply", "Corner board supply"], "industries": ["Automotive", "Aerospace", "Medical", "Pharmaceutical", "Food", "Beverage", "Industrial", "Specialty Manufacturing", "Bakery"], "materials": ["Foam", "Bubble", "Spunbond", "Flexible packaging films", "Tape", "Stretch film", "Labels", "Ribbons", "Strapping", "Corner boards"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Same-day quote response", "Over 50 years of packaging experience", "ISO 9001 certified quality management", "Engineered flexible packaging solutions provider", "Low-cost commodity packaging supplier"], "facts_used": ["Founded 1973 -> db", "Headquarters North Canton, Ohio -> db", "Certifications: ISO9001 -> db", "Industries served: Automotive and aerospace components, Medical and pharmaceutical supplies -> db", "Description: manufacturer of protective packaging, foam, bubble, spunbond, bulk rolls, bags, liners, retention and suspension packaging -> db", "Home page: manufacturer, converter, distributor of flexible, protective, bakery, general-purpose packaging for Food, Beverage, Industrial markets -> /", "Home page: ISO 9001 Certified, ISO 4001 Certified, GDP Certified, Business Excellence Award, Flexible Packaging Achievement Award -> 