UPDATE companies SET description='Restaurant Equipment Solutions operates from Lynn, Massachusetts, serving the North Shore and Greater Boston area. The company was founded in 2016 as a veteran-owned business, established to provide rapid-response commercial kitchen equipment repair and sales with a focus on minimizing costly downtime for foodservice operators.

The company specializes in repair and sales of commercial dishwashers, ovens, and refrigeration systems, along with a full range of restaurant equipment. A CFESA Certified Master Technician leads the technical team, offering onsite service around the clock. Repairs cover heating elements, pump failures, thermostat calibration, ignition systems, and walk-in or reach-in refrigeration units. Every repair is backed by a 30-day parts and labor warranty, with a 90-day parts-only option available.

Customers include independent restaurants, cafés, and foodservice operations throughout the North Shore region. The company supports both emergency breakdowns and planned equipment upgrades, supplying convection ovens, deck ovens, specialty cooking equipment, and energy-efficient refrigeration units suited to professional kitchen demands.

The business was started on the principle that skilled craftsmanship and genuine customer care protect a kitchen''s investment. Veteran ownership and CFESA certification reflect a commitment to technical standards and reliable service delivery when equipment failure threatens daily operations.', certifications=ARRAY['CFESA Certified Master Technician']::text[], profile='{"capabilities": ["Commercial dishwasher repair", "Commercial dishwasher sales", "Commercial oven repair", "Commercial oven sales", "Commercial refrigeration repair", "Commercial refrigeration sales", "Restaurant equipment sales", "Emergency repair service (24/7)", "Onsite service", "Thermostat calibration", "Ignition system repair", "Heating system repair", "Pump failure repair", "Heating element replacement", "Walk-in cooler repair", "Reach-in refrigeration repair"], "industries": ["Restaurant", "Foodservice", "Commercial kitchen", "Caf\u00e9"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["24/7 emergency repair availability", "CFESA Certified Master Technician on staff", "30-day parts and labor warranty on repairs", "90-day parts-only warranty option", "Veteran-owned and operated"], "facts_used": ["Founded 2016 -> db, /, /about", "Veteran-owned business -> db, /, /about", "CFESA Certified Master Technician -> /, /about", "Headquarters Lynn, Massachusetts -> db, /about", "Serves North Shore, MA and Greater Boston -> /, /about", "30-day parts and labor warranty -> /, /about", "90-day parts-only warranty -> /", "24/7 emergency service -> /, /about", "Services: dishwasher, oven, refrigeration repair and sales -> /, /about", "CFESA association membership -> /about", "Onsite service offered -> /about"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, up